package hu.synostream.android;
import org.junit.Test;import static org.junit.Assert.*;import org.json.*;import java.util.*;
public class DownloadsMetricsTest {
 static JSONObject task(String title,String state,long size,long done,long down,long up)throws Exception{return new JSONObject().put("title",title).put("status",state).put("size",size).put("additional",new JSONObject().put("transfer",new JSONObject().put("size_downloaded",done).put("speed_download",down).put("speed_upload",up)));}
 @Test public void columnsSortBothDirectionsWithoutChangingSource()throws Exception{JSONObject a=task("A","paused",100,10,2,1),b=task("B","downloading",100,90,10,8);List<JSONObject> source=List.of(b,a);for(String key:List.of("title","progress","download","upload")){assertSame(a,DownloadsUi.ordered(source,key,false).get(0));assertSame(b,DownloadsUi.ordered(source,key,true).get(0));}for(String key:List.of("status","remaining")){assertSame(b,DownloadsUi.ordered(source,key,false).get(0));assertSame(a,DownloadsUi.ordered(source,key,true).get(0));}assertSame(b,source.get(0));assertEquals(.1,DownloadsUi.metric(a,"progress"),.0001);assertEquals(45,DownloadsUi.metric(a,"remaining"),0);}
 @Test public void unknownSizeAndInvalidRemainingNeverBecomeNegativeTimes()throws Exception{assertTrue(Double.isInfinite(DownloadsUi.metric(task("A","downloading",0,25,10,0),"remaining")));assertTrue(Double.isInfinite(DownloadsUi.metric(task("A","downloading",10,25,10,0),"remaining")));assertEquals(0,DownloadsUi.metric(task("A","finished",25,25,0,0),"remaining"),0);assertEquals("—",DownloadsUi.remainingText(-2));assertEquals("—",DownloadsUi.remainingText(Double.NaN));assertEquals("—",DownloadsUi.remainingText(Double.POSITIVE_INFINITY));assertEquals("1:01:01",DownloadsUi.remainingText(3661));}
}
